CREATE TABLE integration_task(id BIGINT PRIMARY KEY AUTO_INCREMENT,type VARCHAR(64) NOT NULL,business_key VARCHAR(128) NOT NULL,payload LONGTEXT NOT NULL,status VARCHAR(32) NOT NULL,attempts INT NOT NULL DEFAULT 0,next_run_at DATETIME(6) NOT NULL,lease_token VARCHAR(64) NULL,lease_until DATETIME(6) NULL,last_error VARCHAR(255) NULL,created_at DATETIME(6) NOT NULL,UNIQUE(type,business_key),INDEX idx_task_due(status,next_run_at,id),INDEX idx_task_lease(status,lease_until,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
